import hashlib

LLM_SET = "a"

data = _items[0]["json"]["prompts_json"]
prompt_sets = data["prompt_sets"]
cli_settings = data["cli_settings"]

for prompt_set in prompt_sets:
    for task in prompt_set["task"]:
        for prompt in task["prompts"]:

            # Hash the prompt
            prompt["hash"] = hashlib.sha256(
                prompt["prompt"].encode("utf-8")
            ).hexdigest()

            # Build the prompt-specific path
            path = f'/{prompt_set["name"]}/{task["task_number"]}/{prompt["style"]}/'

            if prompt.get("turn") is not None:
                path += f'{prompt["turn"]}/'

            prompt["cli_settings"] = []

            for cli in cli_settings:
                for cli_set in cli["input"]["set"]:

                    # Only use the selected LLM set
                    if cli_set["id"] != LLM_SET:
                        continue

                    prompt["cli_settings"].append({
                        # CLI-level fields
                        "name": cli["name"],
                        "set_id": cli_set["id"],

                        # Flatten common input fields, excluding nested set
                        **{
                            key: value
                            for key, value in cli["input"].items()
                            if key != "set"
                        },

                        # Flatten selected set fields, excluding id
                        **{
                            key: value
                            for key, value in cli_set.items()
                            if key != "id"
                        },

                        # Build unique result path
                        "container_path":
                            f'{cli["container_path"]}/set_{cli_set["id"]}{path}',

                        # Flatten json_output with json_output_ prefix
                        **{
                            f"json_output_{key}": value
                            for key, value in cli["json_output"].items()
                        }
                    })

return prompt_sets
